INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Moon', 'Sun', 'conjunction', 'Góc trùng hợp mang lại sự hợp nhất mãnh liệt giữa Mặt Trăng (thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng) và Mặt Trời (ý chí cá nhân, bản ngã và khát vọng tỏa sáng). Hai nguồn năng lượng hòa cùng một nhịp, định hình một nét cá tính nổi bật và nhất quán.', 'Trong cuộc sống hàng ngày, bạn thể hiện sự gắn kết tự nhiên giữa thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng và ý chí cá nhân, bản ngã và khát vọng tỏa sáng. Mọi phản ứng diễn ra trực tiếp, bộc phát theo bản năng thống nhất của cả hai hành tinh.', 'Sự tập trung năng lượng cao, tinh thần nhất quán nội tâm và khả năng bộc lộ cá tính ấn tượng. (Mặt Trăng - Mặt Trời)', 'Đôi khi khó tách bạch các góc nhìn khác nhau. Dễ bị cuốn vào sự chủ quan khi hai nguồn năng lượng quá hòa nhập. (Mặt Trăng - Mặt Trời)', '', '', ARRAY['Góc chiếu Trùng Hợp', 'Mặt Trăng', 'Mặt Trời']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Moon', 'Sun', 'sextile', 'Góc lục hợp tạo cơ hội thuận lợi và sự hỗ trợ nhịp nhàng giữa Mặt Trăng (thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng) và Mặt Trời (ý chí cá nhân, bản ngã và khát vọng tỏa sáng). Năng lượng tuôn chảy nhẹ nhàng, kích thích tiềm năng phát triển.', 'Trong cuộc sống hàng ngày, bạn dễ dàng kết hợp thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng với ý chí cá nhân, bản ngã và khát vọng tỏa sáng để gặt hái kết quả tích cực và nắm bắt cơ hội một cách hiệu quả.', 'Sự linh hoạt trong tư duy, kỹ năng kết nối tốt và tinh thần chủ động học hỏi, thích ứng nhanh. (Mặt Trăng - Mặt Trời)', 'Nếu không tự giác đặt ra thách thức và hành động, các cơ hội thuận lợi có thể bị trôi qua một cách thụ động. (Mặt Trăng - Mặt Trời)', '', '', ARRAY['Góc chiếu Lục Hợp', 'Mặt Trăng', 'Mặt Trời']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Moon', 'Sun', 'trine', 'Góc tam hợp mang lại dòng chảy hài hòa và sự may mắn tự nhiên giữa Mặt Trăng (thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng) và Mặt Trời (ý chí cá nhân, bản ngã và khát vọng tỏa sáng). Hai hành tinh bổ trợ cho nhau một cách hoàn hảo.', 'Trong cuộc sống hàng ngày, sự kết hợp giữa thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng và ý chí cá nhân, bản ngã và khát vọng tỏa sáng diễn ra vô cùng tự nhiên, không gặp phải sự gượng ép hay trở ngại đáng kể.', 'Tài năng bẩm sinh, sự an ổn trong tâm hồn, sức hút tự nhiên và khả năng gặt hái thành công trôi chảy. (Mặt Trăng - Mặt Trời)', 'Có nguy cơ sinh ra tâm lý tự mãn hoặc thiếu động lực bứt phá khi đối mặt với những thử thách thực sự lớn. (Mặt Trăng - Mặt Trời)', '', '', ARRAY['Góc chiếu Tam Hợp', 'Mặt Trăng', 'Mặt Trời']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Moon', 'Sun', 'square', 'Góc vuông góc tạo ra sự căng thẳng và thử thách nội tâm giữa Mặt Trăng (thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng) và Mặt Trời (ý chí cá nhân, bản ngã và khát vọng tỏa sáng). Đây là động lực áp lực thúc đẩy sự trưởng thành vượt bậc.', 'Trong cuộc sống hàng ngày, bạn thường xuyên cảm thấy sự giằng xé giữa đòi hỏi về thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng và nhu cầu về ý chí cá nhân, bản ngã và khát vọng tỏa sáng.', 'Ý chí kiên cường, bản lĩnh vượt khó phi thường và khả năng chuyển hóa áp lực xung đột thành sức mạnh bứt phá. (Mặt Trăng - Mặt Trời)', 'Dễ rơi vào trạng thái căng thẳng thần kinh hoặc bực bội nội tâm khi chưa học được cách dung hòa hai năng lượng. (Mặt Trăng - Mặt Trời)', '', '', ARRAY['Góc chiếu Vuông Góc', 'Mặt Trăng', 'Mặt Trời']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Moon', 'Sun', 'opposition', 'Góc xung chiếu tạo sự đối lập và đòi hỏi sự cân bằng giữa Mặt Trăng (thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng) và Mặt Trời (ý chí cá nhân, bản ngã và khát vọng tỏa sáng). Hai mặt của một trục năng lượng cần được dung hòa hài hòa.', 'Trong cuộc sống hàng ngày, bạn hay thấy mình đứng giữa hai cực: một bên là thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng và bên kia là ý chí cá nhân, bản ngã và khát vọng tỏa sáng, thường phản chiếu qua các mối quan hệ.', 'Tầm nhìn khách quan đa chiều, khả năng thấu hiểu tâm lý đối phương và năng lực đàm phán, hòa giải tuyệt vời khi đã trưởng thành. (Mặt Trăng - Mặt Trời)', 'Cảm giác dao động mâu thuẫn giữa nhu cầu cá nhân và kỳ vọng từ người khác trước khi đạt được sự cân bằng. (Mặt Trăng - Mặt Trời)', '', '', ARRAY['Góc chiếu Xung Chiếu', 'Mặt Trăng', 'Mặt Trời']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Moon', 'Sun', 'semi-sextile', 'Góc bán lục hợp mang đến sự tương tác tinh tế giữa Mặt Trăng (thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng) và Mặt Trời (ý chí cá nhân, bản ngã và khát vọng tỏa sáng). Hai năng lượng kề nhau thúc đẩy sự tinh chỉnh vi mô liên tục.', 'Trong cuộc sống hàng ngày, bạn nhận thấy những góc nhìn khác biệt nhỏ giữa thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng và ý chí cá nhân, bản ngã và khát vọng tỏa sáng, đòi hỏi sự linh hoạt điều chỉnh trong ứng xử.', 'Khả năng quan sát tinh tế, sự nhạy cảm với các chi tiết nhỏ và năng lực thích ứng linh hoạt. (Mặt Trăng - Mặt Trời)', 'Cảm giác lấn cấn nhỏ dai dẳng nếu không chú ý lắng nghe và đáp ứng các nhu cầu vi mô của bản thân. (Mặt Trăng - Mặt Trời)', '', '', ARRAY['Góc chiếu Bán Lục Hợp', 'Mặt Trăng', 'Mặt Trời']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Moon', 'Sun', 'quincunx', 'Góc bất bất hợp (150°) đòi hỏi sự tái điều chỉnh liên tục giữa Mặt Trăng (thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng) và Mặt Trời (ý chí cá nhân, bản ngã và khát vọng tỏa sáng). Hai nguồn năng lượng không có điểm chung tự nhiên.', 'Trong cuộc sống hàng ngày, bạn cần chủ động sắp xếp để thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng không làm gián đoạn hoặc gây mâu thuẫn với ý chí cá nhân, bản ngã và khát vọng tỏa sáng.', 'Khả năng giải quyết vấn đề tháo vát, tinh thần linh hoạt và năng lực thích nghi với các tình huống bất ngờ. (Mặt Trăng - Mặt Trời)', 'Dễ bị mệt mỏi tinh thần hoặc căng thẳng sức khỏe nhẹ do phải liên tục điều chỉnh nhịp sống. (Mặt Trăng - Mặt Trời)', '', '', ARRAY['Góc chiếu Bất Bất Hợp', 'Mặt Trăng', 'Mặt Trời']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Mercury', 'Sun', 'conjunction', 'Góc trùng hợp mang lại sự hợp nhất mãnh liệt giữa Sao Thủy (tư duy, giao tiếp và khả năng xử lý thông tin) và Mặt Trời (ý chí cá nhân, bản ngã và khát vọng tỏa sáng). Hai nguồn năng lượng hòa cùng một nhịp, định hình một nét cá tính nổi bật và nhất quán.', 'Trong cuộc sống hàng ngày, bạn thể hiện sự gắn kết tự nhiên giữa tư duy, giao tiếp và khả năng xử lý thông tin và ý chí cá nhân, bản ngã và khát vọng tỏa sáng. Mọi phản ứng diễn ra trực tiếp, bộc phát theo bản năng thống nhất của cả hai hành tinh.', 'Sự tập trung năng lượng cao, tinh thần nhất quán nội tâm và khả năng bộc lộ cá tính ấn tượng. (Sao Thủy - Mặt Trời)', 'Đôi khi khó tách bạch các góc nhìn khác nhau. Dễ bị cuốn vào sự chủ quan khi hai nguồn năng lượng quá hòa nhập. (Sao Thủy - Mặt Trời)', '', '', ARRAY['Góc chiếu Trùng Hợp', 'Sao Thủy', 'Mặt Trời']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Mercury', 'Sun', 'sextile', 'Góc lục hợp tạo cơ hội thuận lợi và sự hỗ trợ nhịp nhàng giữa Sao Thủy (tư duy, giao tiếp và khả năng xử lý thông tin) và Mặt Trời (ý chí cá nhân, bản ngã và khát vọng tỏa sáng). Năng lượng tuôn chảy nhẹ nhàng, kích thích tiềm năng phát triển.', 'Trong cuộc sống hàng ngày, bạn dễ dàng kết hợp tư duy, giao tiếp và khả năng xử lý thông tin với ý chí cá nhân, bản ngã và khát vọng tỏa sáng để gặt hái kết quả tích cực và nắm bắt cơ hội một cách hiệu quả.', 'Sự linh hoạt trong tư duy, kỹ năng kết nối tốt và tinh thần chủ động học hỏi, thích ứng nhanh. (Sao Thủy - Mặt Trời)', 'Nếu không tự giác đặt ra thách thức và hành động, các cơ hội thuận lợi có thể bị trôi qua một cách thụ động. (Sao Thủy - Mặt Trời)', '', '', ARRAY['Góc chiếu Lục Hợp', 'Sao Thủy', 'Mặt Trời']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
