INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Pluto', 'Sun', 'trine', 'Góc tam hợp mang lại dòng chảy hài hòa và sự may mắn tự nhiên giữa Sao Diêm Vương (sức mạnh chuyển hóa, chiều sâu tâm lý và sự tái sinh) và Mặt Trời (ý chí cá nhân, bản ngã và khát vọng tỏa sáng). Hai hành tinh bổ trợ cho nhau một cách hoàn hảo.', 'Trong cuộc sống hàng ngày, sự kết hợp giữa sức mạnh chuyển hóa, chiều sâu tâm lý và sự tái sinh và ý chí cá nhân, bản ngã và khát vọng tỏa sáng diễn ra vô cùng tự nhiên, không gặp phải sự gượng ép hay trở ngại đáng kể.', 'Tài năng bẩm sinh, sự an ổn trong tâm hồn, sức hút tự nhiên và khả năng gặt hái thành công trôi chảy. (Sao Diêm Vương - Mặt Trời)', 'Có nguy cơ sinh ra tâm lý tự mãn hoặc thiếu động lực bứt phá khi đối mặt với những thử thách thực sự lớn. (Sao Diêm Vương - Mặt Trời)', '', '', ARRAY['Góc chiếu Tam Hợp', 'Sao Diêm Vương', 'Mặt Trời']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Pluto', 'Sun', 'square', 'Góc vuông góc tạo ra sự căng thẳng và thử thách nội tâm giữa Sao Diêm Vương (sức mạnh chuyển hóa, chiều sâu tâm lý và sự tái sinh) và Mặt Trời (ý chí cá nhân, bản ngã và khát vọng tỏa sáng). Đây là động lực áp lực thúc đẩy sự trưởng thành vượt bậc.', 'Trong cuộc sống hàng ngày, bạn thường xuyên cảm thấy sự giằng xé giữa đòi hỏi về sức mạnh chuyển hóa, chiều sâu tâm lý và sự tái sinh và nhu cầu về ý chí cá nhân, bản ngã và khát vọng tỏa sáng.', 'Ý chí kiên cường, bản lĩnh vượt khó phi thường và khả năng chuyển hóa áp lực xung đột thành sức mạnh bứt phá. (Sao Diêm Vương - Mặt Trời)', 'Dễ rơi vào trạng thái căng thẳng thần kinh hoặc bực bội nội tâm khi chưa học được cách dung hòa hai năng lượng. (Sao Diêm Vương - Mặt Trời)', '', '', ARRAY['Góc chiếu Vuông Góc', 'Sao Diêm Vương', 'Mặt Trời']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Pluto', 'Sun', 'opposition', 'Góc xung chiếu tạo sự đối lập và đòi hỏi sự cân bằng giữa Sao Diêm Vương (sức mạnh chuyển hóa, chiều sâu tâm lý và sự tái sinh) và Mặt Trời (ý chí cá nhân, bản ngã và khát vọng tỏa sáng). Hai mặt của một trục năng lượng cần được dung hòa hài hòa.', 'Trong cuộc sống hàng ngày, bạn hay thấy mình đứng giữa hai cực: một bên là sức mạnh chuyển hóa, chiều sâu tâm lý và sự tái sinh và bên kia là ý chí cá nhân, bản ngã và khát vọng tỏa sáng, thường phản chiếu qua các mối quan hệ.', 'Tầm nhìn khách quan đa chiều, khả năng thấu hiểu tâm lý đối phương và năng lực đàm phán, hòa giải tuyệt vời khi đã trưởng thành. (Sao Diêm Vương - Mặt Trời)', 'Cảm giác dao động mâu thuẫn giữa nhu cầu cá nhân và kỳ vọng từ người khác trước khi đạt được sự cân bằng. (Sao Diêm Vương - Mặt Trời)', '', '', ARRAY['Góc chiếu Xung Chiếu', 'Sao Diêm Vương', 'Mặt Trời']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Pluto', 'Sun', 'semi-sextile', 'Góc bán lục hợp mang đến sự tương tác tinh tế giữa Sao Diêm Vương (sức mạnh chuyển hóa, chiều sâu tâm lý và sự tái sinh) và Mặt Trời (ý chí cá nhân, bản ngã và khát vọng tỏa sáng). Hai năng lượng kề nhau thúc đẩy sự tinh chỉnh vi mô liên tục.', 'Trong cuộc sống hàng ngày, bạn nhận thấy những góc nhìn khác biệt nhỏ giữa sức mạnh chuyển hóa, chiều sâu tâm lý và sự tái sinh và ý chí cá nhân, bản ngã và khát vọng tỏa sáng, đòi hỏi sự linh hoạt điều chỉnh trong ứng xử.', 'Khả năng quan sát tinh tế, sự nhạy cảm với các chi tiết nhỏ và năng lực thích ứng linh hoạt. (Sao Diêm Vương - Mặt Trời)', 'Cảm giác lấn cấn nhỏ dai dẳng nếu không chú ý lắng nghe và đáp ứng các nhu cầu vi mô của bản thân. (Sao Diêm Vương - Mặt Trời)', '', '', ARRAY['Góc chiếu Bán Lục Hợp', 'Sao Diêm Vương', 'Mặt Trời']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Pluto', 'Sun', 'quincunx', 'Góc bất bất hợp (150°) đòi hỏi sự tái điều chỉnh liên tục giữa Sao Diêm Vương (sức mạnh chuyển hóa, chiều sâu tâm lý và sự tái sinh) và Mặt Trời (ý chí cá nhân, bản ngã và khát vọng tỏa sáng). Hai nguồn năng lượng không có điểm chung tự nhiên.', 'Trong cuộc sống hàng ngày, bạn cần chủ động sắp xếp để sức mạnh chuyển hóa, chiều sâu tâm lý và sự tái sinh không làm gián đoạn hoặc gây mâu thuẫn với ý chí cá nhân, bản ngã và khát vọng tỏa sáng.', 'Khả năng giải quyết vấn đề tháo vát, tinh thần linh hoạt và năng lực thích nghi với các tình huống bất ngờ. (Sao Diêm Vương - Mặt Trời)', 'Dễ bị mệt mỏi tinh thần hoặc căng thẳng sức khỏe nhẹ do phải liên tục điều chỉnh nhịp sống. (Sao Diêm Vương - Mặt Trời)', '', '', ARRAY['Góc chiếu Bất Bất Hợp', 'Sao Diêm Vương', 'Mặt Trời']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Mercury', 'Moon', 'conjunction', 'Góc trùng hợp mang lại sự hợp nhất mãnh liệt giữa Sao Thủy (tư duy, giao tiếp và khả năng xử lý thông tin) và Mặt Trăng (thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng). Hai nguồn năng lượng hòa cùng một nhịp, định hình một nét cá tính nổi bật và nhất quán.', 'Trong cuộc sống hàng ngày, bạn thể hiện sự gắn kết tự nhiên giữa tư duy, giao tiếp và khả năng xử lý thông tin và thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng. Mọi phản ứng diễn ra trực tiếp, bộc phát theo bản năng thống nhất của cả hai hành tinh.', 'Sự tập trung năng lượng cao, tinh thần nhất quán nội tâm và khả năng bộc lộ cá tính ấn tượng. (Sao Thủy - Mặt Trăng)', 'Đôi khi khó tách bạch các góc nhìn khác nhau. Dễ bị cuốn vào sự chủ quan khi hai nguồn năng lượng quá hòa nhập. (Sao Thủy - Mặt Trăng)', '', '', ARRAY['Góc chiếu Trùng Hợp', 'Sao Thủy', 'Mặt Trăng']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Mercury', 'Moon', 'sextile', 'Góc lục hợp tạo cơ hội thuận lợi và sự hỗ trợ nhịp nhàng giữa Sao Thủy (tư duy, giao tiếp và khả năng xử lý thông tin) và Mặt Trăng (thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng). Năng lượng tuôn chảy nhẹ nhàng, kích thích tiềm năng phát triển.', 'Trong cuộc sống hàng ngày, bạn dễ dàng kết hợp tư duy, giao tiếp và khả năng xử lý thông tin với thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng để gặt hái kết quả tích cực và nắm bắt cơ hội một cách hiệu quả.', 'Sự linh hoạt trong tư duy, kỹ năng kết nối tốt và tinh thần chủ động học hỏi, thích ứng nhanh. (Sao Thủy - Mặt Trăng)', 'Nếu không tự giác đặt ra thách thức và hành động, các cơ hội thuận lợi có thể bị trôi qua một cách thụ động. (Sao Thủy - Mặt Trăng)', '', '', ARRAY['Góc chiếu Lục Hợp', 'Sao Thủy', 'Mặt Trăng']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Mercury', 'Moon', 'trine', 'Góc tam hợp mang lại dòng chảy hài hòa và sự may mắn tự nhiên giữa Sao Thủy (tư duy, giao tiếp và khả năng xử lý thông tin) và Mặt Trăng (thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng). Hai hành tinh bổ trợ cho nhau một cách hoàn hảo.', 'Trong cuộc sống hàng ngày, sự kết hợp giữa tư duy, giao tiếp và khả năng xử lý thông tin và thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng diễn ra vô cùng tự nhiên, không gặp phải sự gượng ép hay trở ngại đáng kể.', 'Tài năng bẩm sinh, sự an ổn trong tâm hồn, sức hút tự nhiên và khả năng gặt hái thành công trôi chảy. (Sao Thủy - Mặt Trăng)', 'Có nguy cơ sinh ra tâm lý tự mãn hoặc thiếu động lực bứt phá khi đối mặt với những thử thách thực sự lớn. (Sao Thủy - Mặt Trăng)', '', '', ARRAY['Góc chiếu Tam Hợp', 'Sao Thủy', 'Mặt Trăng']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
